repo_files.semver.py:
"""Semantic version representation."""

from dataclasses import dataclass
from typing import Optional, Tuple


@dataclass
class SemVer:
    major: int
    minor: int
    patch: int
    prerelease: Optional[str] = None

    @classmethod
    def parse(cls, version_str: str) -> "SemVer":
        clean = version_str.strip().lstrip("v")
        pre = None
        if "-" in clean:
            clean, pre = clean.split("-", 1)
        parts = list(map(int, clean.split(".")))
        while len(parts) < 3:
            parts.append(0)
        return cls(parts[0], parts[1], parts[2], pre)

repo_files.matcher.py:
"""SemVer comparison and ordering engine."""

from semver import SemVer


class SemVerComparator:
    @staticmethod
    def compare(v1: SemVer, v2: SemVer) -> int:
        """Returns -1 if v1 < v2, 0 if v1 == v2, 1 if v1 > v2."""
        if (v1.major, v1.minor, v1.patch) != (v2.major, v2.minor, v2.patch):
            t1 = (v1.major, v1.minor, v1.patch)
            t2 = (v2.major, v2.minor, v2.patch)
            return 1 if t1 > t2 else -1

        # Handle Prerelease precedence: standard release has HIGHER precedence than pre-release
        # e.g., 1.0.0 > 1.0.0-alpha
        # BUG: Inverted logic treats prerelease as greater than release
        if v1.prerelease is None and v2.prerelease is not None:
            return -1  # BUG: Should be +1
        if v1.prerelease is not None and v2.prerelease is None:
            return 1   # BUG: Should be -1

        if v1.prerelease == v2.prerelease:
            return 0
        return 1 if str(v1.prerelease) > str(v2.prerelease) else -1

